mapper.select:
SELECT 
  FROM tb_kms_approvals
 WHERE institution_id = #{institutionId}
   AND consumed_at IS NULL
   AND expires_at > #{now}
 ORDER BY created_at DESC, id DESC

mapper.update:
UPDATE tb_kms_approvals
   SET consumed_at = #{now}, consumed_by_operation_id = #{operationId}
 WHERE id = #{approvalId}
   AND consumed_at IS NULL
   AND expires_at > #{now}
   AND institution_id = #{institutionId} AND purpose = #{purpose} AND action = #{action}
   AND approved_by <> #{requester}
   AND sign_key_id = #{signKeyId}
   AND expected_version = #{currentVersion}
   AND target_key_version IS NOT DISTINCT FROM #{targetKeyVersion, jdbcType=INTEGER}
   AND target_compromised_at IS NOT DISTINCT FROM #{targetCompromisedAt, jdbcType=TIMESTAMP_WITH_TIMEZONE}
   AND params_hash = #{paramsHash}
